pgp_get_blob(sc_card_t *card, pgp_blob_t *blob, unsigned int id,
                pgp_blob_t **ret)
{
        pgp_blob_t              *child;
        int                     r;

        if ((r = pgp_enumerate_blob(card, blob)) < 0)
